if ( ! defined( 'ABSPATH' ) ) { exit; } $a = is_array( $attributes ?? null ) ? $attributes : array(); $tone = in_array( $a['tone'] ?? 'info', array( 'info', 'tip', 'success', 'warning', 'danger' ), true ) ? $a['tone'] : 'info'; $icons = array( 'info' => 'i', 'tip' => '✦', 'success' => '✓', 'warning' => '!', 'danger' => '×' ); $icon = ! isset( $a['showIcon'] ) || $a['showIcon'] ? '<span class="bigspy-callout__icon" aria-hidden="true">' . esc_html( $icons[ $tone ] ) . '</span>' : ''; echo '<aside ' . get_block_wrapper_attributes( array( 'class' => 'bigspy-callout bigspy-callout--' . $tone ) ) . '>' . $icon . '<div class="bigspy-callout__content">' . ( ! empty( $a['title'] ) ? '<strong class="bigspy-callout__title">' . esc_html( wp_strip_all_tags( $a['title'] ) ) . '</strong>' : '' ) . '<p>' . wp_kses_post( $a['text'] ?? '' ) . '</p></div></aside>';